extends Resource
class_name DialogChoice

## A single choice option presented to the player during a dialog.
## A choice with a non-empty [member condition_flag] is only visible
## when that flag has been set on the [DialogPlayer] via [method DialogPlayer.set_flag].

@export var label: String = ""
@export var next_id: StringName = &""
@export var condition_flag: StringName = &""

extends Resource
class_name DialogNode

## One node in a branching dialog tree.
## When [member choices] is non-empty the player must pick one;
## otherwise [member next_id] is followed REDACTEDmatically.

@export var id: StringName = &""
@export var speaker: String = ""
@export var text: String = ""
@export var choices: Array[DialogChoice] = []
@export var next_id: StringName = &""

extends Resource
class_name DialogTree

## A complete branching dialog tree made up of [DialogNode] resources.

@export var nodes: Array[DialogNode] = []
@export var start_id: StringName = &""


## Returns the [DialogNode] whose [member DialogNode.id] matches [param id],
## or [code]null[/code] if no such node exists.
func get_node(id: StringName) -> DialogNode:
	for n in nodes:
		if n.id == id:
			return n
	return null

class_name DialogPlayer
extends Node

## Drives playback of a [DialogTree] resource.
## Emit [signal line_shown] each time a new node is presented and
## [signal dialog_finished] when the conversation ends.

@export var tree: DialogTree

signal line_shown(speaker: String, text: String, choices_labels: Array)
signal dialog_finished

var _current_id: StringName = &""
var _flags: Dictionary = {}


## Begins playback at [member DialogTree.start_id].
func start() -> void:
	_current_id = tree.start_id
	_show_current()


## Follows the chosen branch when the current node has visible choices,
## or follows [member DialogNode.next_id] when there are no choices.
## If the current node has empty [member DialogNode.choices] and empty
## [member DialogNode.next_id], emits [signal dialog_finished] and stops.
func advance(choice_index: int = -1) -> void:
	var current_node := tree.get_node(_current_id)
	if current_node == null:
		dialog_finished.emit()
		return

	var visible_choices := _get_visible_choices(current_node)
	if visible_choices.size() > 0:
		if choice_index >= 0 and choice_index < visible_choices.size():
			_current_id = visible_choices[choice_index].next_id
			_show_current()
		return

	# No choices – follow next_id
	if current_node.next_id != &"":
		_current_id = current_node.next_id
		_show_current()
	else:
		dialog_finished.emit()


## Sets the flag [param name] so that choices whose [member DialogChoice.condition_flag]
## matches it become visible.
func set_flag(name: StringName) -> void:
	_flags[name] = true


## Returns [code]true[/code] if the flag [param name] has been set.
func has_flag(name: StringName) -> bool:
	return _flags.has(name)


func _show_current() -> void:
	var current_node := tree.get_node(_current_id)
	if current_node == null:
		dialog_finished.emit()
		return

	var labels: Array = []
	for choice in current_node.choices:
		if choice.condition_flag == &"" or has_flag(choice.condition_flag):
			labels.append(choice.label)

	line_shown.emit(current_node.speaker, current_node.text, labels)


func _get_visible_choices(node: DialogNode) -> Array:
	var visible: Array = []
	for choice in node.choices:
		if choice.condition_flag == &"" or has_flag(choice.condition_flag):
			visible.append(choice)
	return visible

extends Control

## UI controller that renders the current dialog line and choice buttons.
## Connects to a [DialogPlayer] child node and updates the speaker [Label],
## [RichTextLabel] body, and [VBoxContainer] choice buttons whenever
## [signal DialogPlayer.line_shown] fires.

@onready var speaker_label: Label = $SpeakerLabel
@onready var body_text: RichTextLabel = $BodyText
@onready var choices_container: VBoxContainer = $ChoicesContainer

var dialog_player: DialogPlayer


func _ready() -> void:
	dialog_player = get_node_or_null("DialogPlayer") as DialogPlayer
	if dialog_player == null:
		push_error("DialogUI: no DialogPlayer child node found")
		return

	dialog_player.line_shown.connect(_on_line_shown)
	dialog_player.dialog_finished.connect(_on_dialog_finished)
	dialog_player.start()


func _on_line_shown(speaker: String, text: String, choices_labels: Array) -> void:
	speaker_label.text = speaker
	body_text.text = text

	# Clear existing buttons
	for child in choices_container.get_children():
		child.queue_free()

	# Build new buttons from the visible choice labels
	for i in range(choices_labels.size()):
		var label_text: String = choices_labels[i]
		var button := Button.new()
		button.text = label_text
		button.pressed.connect(_on_choice_pressed.bind(i))
		choices_container.add_child(button)


func _on_choice_pressed(index: int) -> void:
	if dialog_player:
		dialog_player.advance(index)


func _on_dialog_finished() -> void:
	speaker_label.text = ""
	body_text.text = "[i]Dialog finished.[/i]"
	for child in choices_container.get_children():
		child.queue_free()
